        uint256 balanceHeight;
        bytes voteTo;
        uint256 lastGasPerVote;
    }

    struct ContractState {
        address hash;
        bytes nef;
        bytes manifest;
        uint256 updateCounter;
    }

    struct WhitelistedContract {
        address contractHash;
        string method;
        uint256 argCount;
        int256 fixedFee;
    }

    // ========== Helper Functions ==========

    /**
     * @dev Check if native contract exists
     */
