// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title Neo N3 Native Contract Addresses
 * @dev Canonical script hash constants for Neo N3 native contracts and core libraries.
 *
 * These addresses are deterministic and identical on all Neo N3 networks
 * (MainNet/TestNet/private networks).
 *
 * NOTE: These are written in Neo RPC-style big-endian hex (same values you
 * see via RPC/explorer). The compiler lowers `address` literals to NeoVM
 * `Hash160` stack representation as needed.
 */
library NativeContracts {
    address constant NEO_CONTRACT = 0xef4073a0f2b305a38ec4050e4d3d28bc40ea63f5;
    address constant GAS_CONTRACT = 0xd2a4cff31913016155e38e474a2c06d08be276cf;
    address constant CONTRACT_MANAGEMENT = 0xfffdc93764dbaddd97c48f252a53ea4643faa3fd;
    address constant POLICY_CONTRACT = 0xcc5e4edd9f5f8dba8bb65734541df7a1c081c67b;
    address constant ORACLE_CONTRACT = 0xfe924b7cfe89ddd271abaf7210a80a7e11178758;
    address constant ROLE_MANAGEMENT = 0x49cf4e5378ffcd4dec034fd98a174c5491e395e2;
    address constant NOTARY_CONTRACT = 0xc1e14f19c3e60d0b9244d06dd7ba9b113135ec3b;
    address constant TREASURY_CONTRACT = 0x156326f25b1b5d839a4d326aeaa75383c9563ac1;
    address constant LEDGER_CONTRACT = 0xda65b600f7124ce6c79950c1772a36403104f2be;
    address constant CRYPTO_LIB = 0x726cb6e0cd8628a1350a611384688911ab75f51b;
    address constant STD_LIB = 0xacce6fd80d44e1796aa0c2c625e9e4e0ce39efc0;
}

contracts/NeoBytes.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title NeoBytes
 * @dev Byte parsing helpers for NeoVM-oriented ABI/data bridge handling.
 */
abstract contract NeoBytes {
    /**
     * @dev Check whether every item is exactly 1 byte.
     */
    function nbAllSingleByteItems(bytes[] calldata items) internal pure returns (bool) {
        for (uint256 i = 0; i < items.length; i++) {
            if (items[i].length != 1) {
                return false;
            }
        }
        return true;
    }

    /**
     * @dev Flatten an array of byte slices into one contiguous buffer.
     */
    function nbFlattenItems(bytes[] calldata items) internal pure returns (bytes memory out) {
        uint256 total = 0;
        for (uint256 i = 0; i < items.length; i++) {
            total += items[i].length;
        }

        out = new bytes(total);
        uint256 offset = 0;
        for (uint256 i = 0; i < items.length; i++) {
            bytes calldata item = items[i];
            for (uint256 j = 0; j < item.length; j++) {
                out[offset++] = item[j];
            }
        }
    }

    /**
     * @dev Read a 32-byte unsigned integer from big-endian memory bytes at `start`.
     */
    function nbBytesToUintBE(bytes memory raw, uint256 start) internal pure returns (uint256 value) {
        if (start + 32 > raw.length) {
            return 0;
        }

        for (uint256 i = 0; i < 32; i++) {
            value = (value << 8) | uint256(uint8(raw[start + i]));
        }
    }

    /**
     * @dev Decode UTF-8 string slice from bytes range.
     */
    function nbBytesToString(bytes memory raw, uint256 start, uint256 len) internal pure returns (string memory) {
        if (start + len > raw.length) {
            return "";
        }

        bytes memory out = new bytes(len);
        for (uint256 i = 0; i < len; i++) {
            out[i] = raw[start + i];
        }
        return string(out);
    }

    /**
     * @dev Decode little-endian uint from memory bytes (up to 32 bytes).
     */
    function nbBytesToUintLE(bytes memory raw) internal pure returns (uint256 value) {
        uint256 len = raw.length;
        if (len > 32) {
            len = 32;
        }

        for (uint256 i = 0; i < len; i++) {
            value |= uint256(uint8(raw[i])) << (8 * i);
        }
    }

    /**
     * @dev Decode little-endian uint from calldata bytes (up to 32 bytes).
     */
    function nbBytesToUintLE(bytes calldata raw) internal pure returns (uint256 value) {
        uint256 len = raw.length;
        if (len > 32) {
            len = 32;
        }

        for (uint256 i = 0; i < len; i++) {
            value |= uint256(uint8(raw[i])) << (8 * i);
        }
    }
}

